@startuml

class Person {
  + firstName : string
  + familyName : string
  + birthDate : date
}

class Trainer {
  + diploma : string
}

class Member {
  + memberID : string
}

class Prospect {
}

class Room {
  + roomNumber : int
  + maxCapacity : int
}

class FitnessCenter {
  + name : string
  + address : string
}

abstract class Session {
  + date : date
  + startTime : time
}

class IndividualSession {}

class GroupSession {
  + sessionType : string
}

Trainer --|> Person
Member --|> Person
Prospect --|> Person

FitnessCenter "1" *-- "1..*" Room
Room "1" -- "0..*" Session

Session "0..*" -- "0..1" Room : heldIn

GroupSession "0..*" -- "1" Trainer : supervisedBy
Session "0..*" -- "0..*" Person : participatedBy

Member "0..*" -- "0..*" Session : registersFor
Trainer "0..*" -- "0..*" Session : supervises
@enduml

